// infra/modules/observability/canary-src/nodejs/node_modules/heartbeat.js
//
// CloudWatch Synthetics heartbeat — verifica que a URL pública responde
// 200 a cada execução. TARGET_URL vem de run_config.environment_variables
// (canary.tf), não hardcoded aqui, para o mesmo script servir dev/prod.

const { URL } = require('url');
var synthetics = require('Synthetics');
const log = require('SyntheticsLogger');

const heartbeat = async function () {
  const url = process.env.TARGET_URL;
  if (!url) {
    throw new Error('TARGET_URL não definida nas environment_variables do canary');
  }

  await synthetics.executeStep('verify_' + new URL(url).hostname, async function (timeoutInMillis) {
    const page = await synthetics.getPage();
    const response = await page.goto(url, { waitUntil: ['load', 'networkidle0'], timeout: timeoutInMillis });

    if (!response) {
      throw new Error('Nenhuma resposta recebida de ' + url);
    }

    const status = response.status();
    if (status < 200 || status > 299) {
      throw new Error('Status HTTP inesperado (' + status + ') em ' + url);
    }

    log.info('Heartbeat OK: ' + url + ' -> ' + status);
  });
};

exports.handler = async () => {
  return await heartbeat();
};
